use verus::prelude::*;

verus! {

    /// Returns true iff `n` is strictly greater than every element of `a`.
    fn is_greater(n: i32, a: &Vec<i32>) -> bool
        // the array is assumed non‐empty
        requires a.len() > 0
        // the result is true exactly when ∀i ∈ [0, a.len()) ⇒ n > a[i]
        ensures  result <==>
                 forall |i: int|
                     0 <= i && i < (a.len() as int)
                     ==> n > a[i as usize]
    {
        // proof‐style skeleton: we walk the array and maintain an
        // invariant that so far all elements are below n.
        let mut i: usize = 0;
        let mut ok: bool = true;
        while i < a.len()
            invariant
                // i stays in bounds
                0 <= (i as int) && (i as int) <= (a.len() as int)
                &&
                // ok reflects “∀ j < i, n > a[j]”
                ok <==>
                forall |j: int|
                    0 <= j && j < (i as int)
                    ==> n > a[j as usize]
            decreases
                // we make progress
                (a.len() as int) - (i as int)
        {
            // safety check (always true given the loop guard)
            assert(i < a.len());

            // if we ever see an element ≥ n, we know the answer is false
            if !(n > a[i]) {
                ok = false;
                break;
            }

            i += 1;
        }

        ok
    }

}